{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "In rats, intravenous administration of orientin/isoorientin (luteolin C-glucoside, the query scaffold) resulted in low brain levels and was classified as impermeable across the BBB due to high polarity, directly indicating insufficient CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Isovitexin, a close C-glucoside analogue with one fewer B-ring hydroxyl, was detected in rat brain at ~14.7 ng/mL after IV administration and labeled permeable, showing that some flavone C-glucosides can access the CNS.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "Cyanidin-3-O-glucoside was detected in mouse brain after intraperitoneal injection, providing evidence that some glycosylated flavonoids can access the brain, but this is from a different chemical class (anthocyanin O-glucoside).",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct experimental evidence shows the query's luteolin C-glucoside scaffold is impermeable across the BBB in rats; close analogue isovitexin crosses, but the query's additional B-ring hydroxyl increases polarity and likely prevents meaningful CNS access.",
  "evidence_gaps": [
    "Single negative study for the exact scaffold; no quantitative brain/plasma ratio or unbound brain concentration reported.",
    "Positive isovitexin evidence is from a less polar analogue and may not transfer to the query's catechol-containing B-ring.",
    "No data on efflux transporter involvement or potential active uptake mechanisms for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

